const item = $input.first();
const json = item.json || {};

const pick = (...keys) => {
  for (const key of keys) {
    const value = json[key];
    if (value !== undefined && value !== null && String(value).trim() !== '') {
      return String(value);
    }
  }
  return '';
};

const logs = pick('Error logs', 'error_logs', 'errorLogs', 'logs');
const steps = pick('Steps to reproduce', 'steps_to_reproduce', 'stepsToReproduce', 'steps');
const severity = pick('Severity guess', 'severity_guess', 'severity');
const environment = pick('Environment', 'environment');

const binary = item.binary || {};
const binaryKey = Object.keys(binary)[0];
if (!binaryKey) {
  throw new Error('No uploaded file found on the trigger item. Add a file field to the form.');
}
const screenshot = binary[binaryKey];

const systemPrompt = `You are a senior QA engineer triaging a screenshot.

FIRST decide whether the screenshot actually shows a defect. Many screenshots show
a perfectly healthy screen. If this one does, say so: set confidence to "low" and
write a summary stating that no defect is visible. Do not manufacture a defect to
fill the schema. "Nothing is wrong here" is a correct and valuable answer.

The reporter severity guess below is only a guess. It is NOT evidence that a defect
exists and must not steer what you claim to see. Neither is the fact that someone
asked you for a report.

Only once you have decided a defect is visible, write it up.

Rules:
- Describe only what is actually visible in the image. Never invent stack traces,
  error codes, URLs, ids or user names that you cannot actually read.
- If the reporter supplied error logs, use them. Do not fabricate extra log lines.
- Quote on-screen text exactly as rendered. Never claim that text is truncated, cut
  off or clipped unless you can name the exact character it stops at.
- A screenshot being tall, wide or scaled is not a defect. Do not report cropping
  that is an artifact of how the image was captured.
- steps_to_reproduce must be concrete actions a second tester could follow. If you
  are inferring them rather than reading them, keep them short and lower confidence.
- visual_observations is where the screenshot detail belongs: layout breaks,
  overlapping elements, error banners, empty states, truncated or misaligned text,
  wrong colours, and the exact on-screen error strings you can read.
- severity is one of S1, S2, S3, S4. S1 blocks release, S4 is cosmetic.
- confidence is one of high, medium, low.

Return a single JSON object with exactly these keys:
summary, environment, steps_to_reproduce, expected_result, actual_result,
visual_observations, severity, suggested_component, confidence

summary is one line under 120 characters with no ticket prefix.
steps_to_reproduce and visual_observations are arrays of strings.
Every other value is a string.`;

const userPrompt = [
  'Examine the attached screenshot. Decide first whether it shows a defect, then report what you find. If nothing is wrong with it, report that.',
  '',
  'Reporter severity guess: ' + (severity || 'not supplied'),
  'Environment: ' + (environment || 'not supplied'),
  '',
  steps ? 'What the reporter did:\n' + steps : 'What the reporter did: not supplied.',
  '',
  logs ? 'Error logs:\n' + logs : 'Error logs: none supplied.'
].join('\n');

return [{
  json: {
    logs,
    steps,
    severity,
    environment,
    system_prompt: systemPrompt,
    user_prompt: userPrompt,
    screenshot_mime: screenshot.mimeType || 'image/png',
    screenshot_name: screenshot.fileName || 'screenshot.png'
  },
  binary: { screenshot }
}];

const response = $input.first().json;
const choice = (response.choices && response.choices[0]) || {};
const message = choice.message || {};
let text = String(message.content || '').trim();

const fenced = text.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
if (fenced) {
  text = fenced[1].trim();
}

const asArray = (value) => {
  if (Array.isArray(value)) {
    return value.map((v) => String(v)).filter((v) => v.trim() !== '');
  }
  if (value === undefined || value === null || String(value).trim() === '') {
    return [];
  }
  return [String(value)];
};
const asString = (value) => (value === undefined || value === null ? '' : String(value));

let report;
let processingError = '';
try {
  report = JSON.parse(text);
} catch (error) {
  processingError = 'Model did not return valid JSON: ' + error.message;
  report = {};
}

const steps = asArray(report.steps_to_reproduce);
const visual = asArray(report.visual_observations);
const summary = asString(report.summary) || 'Screenshot bug report (summary unavailable)';

const description = [
  'Summary: ' + summary,
  '',
  'Environment: ' + asString(report.environment),
  'Severity (model): ' + asString(report.severity),
  'Suggested component: ' + asString(report.suggested_component),
  'Confidence: ' + asString(report.confidence),
  '',
  'Steps to reproduce:',
  steps.length ? steps.map((s, i) => `${i + 1}. ${s}`).join('\n') : '(not supplied)',
  '',
  'Expected result: ' + asString(report.expected_result),
  'Actual result: ' + asString(report.actual_result),
  '',
  'Visual observations:',
  visual.length ? visual.map((v) => '- ' + v).join('\n') : '(not supplied)'
].join('\n');

const source = $('Normalize Intake').first();
const binary = source.binary || {};

return [{
  json: {
    summary: summary.slice(0, 240),
    environment: asString(report.environment),
    severity: asString(report.severity),
    suggested_component: asString(report.suggested_component),
    confidence: asString(report.confidence),
    steps_to_reproduce: steps,
    visual_observations: visual,
    jira_description: processingError
      ? description + '\n\nProcessing error: ' + processingError
      : description,
    screenshot_mime: source.json.screenshot_mime || 'image/png',
    processing_error: processingError
  },
  binary
}];

const created = $input.first().json;
const source = $('Normalize Intake').first();
const binary = source.binary || {};

return [{
  json: {
    issue_key: created.key || created.id || '',
    issue_id: created.id || '',
    screenshot_mime: source.json.screenshot_mime || 'image/png'
  },
  binary
}];
